def minPath(grid, k):
    N = len(grid)
    visited = [[False]*N for _ in range(N)]

    def dfs(i, j, path, count):
        if count == k:
            return path

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        min_val = float('inf')
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and not visited[ni][nj]:
                new_path = path + [grid[ni][nj]]
                visited[ni][nj] = True

                min_val = min(min_val, grid[ni][nj])

                result = dfs(ni, nj, new_path, count+1)
                if result:
                    return result

        return None

    for i in range(N):
        for j in range(N):
            visited[i][j] = False

            path = [grid[i][j]]

            res = dfs(i, j, path, 0)
            if res and grid[res[0]][res[-1]] < min_val:
                return res

    return []

