    else:
        return max(a, b)

def is_equal_to_sum_even(n):
    for i in range(2, n//3 + 1, 2):
        for j in range(i, (n - i)//2 + 1, 2):
            for k in range(j, (n - i - j)//2 + 1, 2):
                l = n - i - j - k
                if l > 0 and l % 2 == 0:
                    return True
    return False

def special_factorial(n):
    result = 1
    for i in range(n, 0, -1):
        result *= math.factorial(i)
    return result

def fix_spaces(text):
    text = text.replace(' ', '_')
    while '  ' in text:
        text = text.replace('  ', '-')
    return text.strip('_')

def file_name_check(file_name):
    if len([char for char in file_name if char.isdigit()]) > 3:
        return 'No'
    elif '.' not in file_name or file_name.split('.')[0] == '':
        return 'No'
    elif not file_name.split('.')[0][0].isalpha():
        return 'No'
    else:
        extensions = ['txt', 'exe', 'dll']
        if file_name.split('.')[-1] not in extensions:
            return 'No'
        else:
            return 'Yes'

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result = ''
    for word in words:
        if is_prime(len(word)):
            result += ' ' + word
    return result.strip()

def specialFilter(nums):
    count = 0
    for num in nums:
        if abs(num) > 10 and (num % 10 + num // 10) % 2 != 0:
            count += 1
    return count

def get_max_triples(n):
    arr = [(i * i - i + 1) for i in range(1, n+1)]
    count = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            for k in range(j+1, len(arr)):
                if (arr[i] + arr[j] + arr[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)
    between_planets = [p for p in planets[idx1+1:idx2] if p != planet1 and p != planet2]
    return tuple(between_planets)

def x_or_y(n, x, y):
    if n > 1:
        is_prime = True
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                is_prime = False
                break
        return x if is_prime else y
    else:
        return y

def cycpattern_check(a, b):
    for i in range(len(b)):
        if b[i:] + b[:i] in a:
            return True
    return False

def int_to_mini_roman(number):
    roman = {1000: 'm', 900: 'cm', 500: 'd', 400: 'cd',
            100: 'c', 90: 'xc', 50: 'l', 40: 'xl',
            10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'}
    result = ''
    for value, numeral in roman.items():
        while number >= value:
            result += numeral
            number -= value
    return result.lower()

def find_max(words):
    max_len = 0
    result = ""
    for word in words:
        if len(set(word)) > max_len or (len(set(word)) == max_len and word < result):
            max_len = len(set(word))
            result = word
    return result

def do_algebra(operator, operand):
    expression = ''
    for i in range(len(operand) - 1):
        expression += str(operand[i]) + operator[i]
    return eval(expression + str(operand[-1]))

def solve(s):
    result = ""
    for char in s:
        if 'a' <= char.lower() <= 'z':
            result += char.swapcase()
        elif 'A' <= char <= 'Z':
            result += char.swapcase()
        else:
            result += char
    return result[::-1] if not any('a' <= c <= 'z' for c in s) else result

def string_to_md5(text):
    import hashlib
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    even_digits = set()
    for i in range(min(a,b), max(a,b)+1):
        if i % 2 == 0:
            even_digits.add(i)
    return sorted(list(even_digits))
